export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

const posts: Post[] = []

export function getPosts(): Post[] {
  return [...posts].sort((a, b) => b.createdAt.localeCompare(a.createdAt))
}

export function savePost(title: string, content: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }
  posts.push(post)
  return post
}

